draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // fog
  ctx.fillStyle = 'rgba(128, 128, 128, 0.5)';
  ctx.fillRect(0, H/2, W, H/2);

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2, H/2 + 20);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 - 20, H/2);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10);
  ctx.lineTo(W/2 + 20, H/2);
  ctx.stroke();

  // attempt to move
  ctx.beginPath();
  ctx.moveTo(W/2 + 20 + 10 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 20, H/2);
  ctx.stroke();

  ctx.restore();
}
